import pygame


def make_surface(text: str, color: tuple = (0, 0, 0), size: int = 30) -> pygame.Surface:
    """ Retourne une surface de texte 'text' """

    font = pygame.font.SysFont('couriernew', size)
    return font.render(text, True, color)


def make_version(text: str) -> pygame.Surface:
    """ Gestion d'affichage des versions """

    font = pygame.font.SysFont('couriernew', 20)
    for i in text.split():
        if len(i) > 9:
            font = pygame.font.SysFont('couriernew', 15)
            break
    texts = text.split(" ")
    width, height = 0, 0
    liste = list()
    for t in texts:
        text = font.render(t, True, (0, 0, 0))
        liste.append(text)
        height += text.get_height()
        if text.get_width() > width:
            width = text.get_width()

    surface = pygame.Surface((width, height))
    surface.fill((240, 240, 240))
    height = 0
    for i in liste:
        surface.blit(i, (width / 2 - i.get_width() / 2, height))
        height += i.get_height()

    return surface


def make_local(localisations: list) -> pygame.Surface:
    """ Gestion d'affichage des localisation """

    font = pygame.font.SysFont('couriernew', 20)
    width, height = 0, 0
    liste = list()
    mot = ""
    local = list()

    for l in localisations:
        if len(l) > 25:
            for i in l.split(" "):
                local.append(i)
        else:
            local.append(l)

    for t in local:
        if len(mot + t + "   ") > 25:
            text = font.render(mot, True, (0, 0, 0))
            liste.append(text)
            if text.get_width() > width:
                width = text.get_width()
            height += text.get_height()
            mot = ""
        mot += t + "   "
        if len(liste) == 6:
            break

    if len(liste) <= 6:
        text = font.render(mot, True, (0, 0, 0))
        liste.append(text)
        if text.get_width() > width:
            width = text.get_width()
        height += text.get_height()

    surface = pygame.Surface((width, height))
    surface.fill((240, 240, 240))
    height = 0
    for i in liste:
        surface.blit(i, (width / 2 - i.get_width() / 2, height))
        height += i.get_height()

    return surface


